catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading) return;

    var total = 0;
    var rows = g_form.getMultipleRowValues('menu_items'); // Replace with actual MRVS name

    rows.forEach(function(row) {
        var price = row.food_price;
       // var quantity = row.quantity;

        if (price ) {
            total += price ;
        }
    });

    g_form.setValue('total_price', total);
}
